@Service
@Transactional(readOnly = true)
public class ListMemberLoansService implements ListMemberLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadActiveLoansPort loadActiveLoansPort;

    public ListMemberLoansService(LoadMemberPort loadMemberPort, LoadActiveLoansPort loadActiveLoansPort) {
