package com.example.lending.domain;

import java.util.Objects;
import java.util.UUID;

public class Reservation {

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    // 책별로 증가하는 순번. 작을수록 먼저 예약한 사람이다
    private final long sequenceNo;
    private boolean fulfilled;

    private Reservation(UUID id, UUID bookId, UUID memberId, long sequenceNo, boolean fulfilled) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.sequenceNo = sequenceNo;
        this.fulfilled = fulfilled;
    }

    public static Reservation place(UUID bookId, UUID memberId, long sequenceNo) {
        return new Reservation(UUID.randomUUID(), bookId, memberId, sequenceNo, false);
    }

    public static Reservation reconstitute(UUID id, UUID bookId, UUID memberId, long sequenceNo, boolean fulfilled) {
