import com.example.lending.application.port.in.ReserveBookUseCase;
import com.example.lending.application.port.in.ReserveBookUseCase.ReserveBookCommand;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/books/{bookId}/reservations")
public class ReservationController {

    private final ReserveBookUseCase reserveBookUseCase;
    private final ListReservationsUseCase listReservationsUseCase;

    public ReservationController(ReserveBookUseCase reserveBookUseCase,
                                 ListReservationsUseCase listReservationsUseCase) {
        this.reserveBookUseCase = reserveBookUseCase;
        this.listReservationsUseCase = listReservationsUseCase;
    }

    // 대출 중인 책에 예약을 건다. 줄의 맨 뒤에 서며, position 은 줄에서의 순서(1부터)다
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ReservationResponse reserveBook(@PathVariable UUID bookId, @RequestBody ReserveBookRequest request) {
        ReservationQueueItem item = reserveBookUseCase.reserveBook(new ReserveBookCommand(bookId, request.memberId()));
        return new ReservationResponse(item.reservationId(), item.position());
    }

    // 소진되지 않은 예약을 맨 앞부터 돌려준다
    @GetMapping
    public List<ReservationItemResponse> listReservations(@PathVariable UUID bookId) {
        return listReservationsUseCase.listReservations(bookId).stream()
                .map(item -> new ReservationItemResponse(item.reservationId(), item.memberId(), item.position()))
                .toList();
    }
}
