package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookReservationIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void reserving_a_book_on_loan_returns_201_with_position_1() throws Exception {
        String lender = registerMember();
        String reserver = registerMember();
        String bookId = registerBook("On Loan Atlas");
        loanBook(bookId, lender);

        reserve(bookId, reserver)
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.reservationId").isNotEmpty())
                .andExpect(jsonPath("$.position").value(1));
    }

    @Test
    void reservations_on_the_same_book_are_queued_in_order() throws Exception {
        String lender = registerMember();
        String first = registerMember();
        String second = registerMember();
        String bookId = registerBook("Queued Atlas");
        loanBook(bookId, lender);

        reserve(bookId, first).andExpect(jsonPath("$.position").value(1));
        reserve(bookId, second).andExpect(jsonPath("$.position").value(2));

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].memberId").value(first))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[1].memberId").value(second))
                .andExpect(jsonPath("$[1].position").value(2));
    }

    @Test
    void reserving_an_available_book_returns_409_with_book_available_error() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Shelf Atlas");

        reserve(bookId, memberId)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_AVAILABLE"));
    }

    @Test
    void reserving_a_discarded_book_returns_409_with_book_discarded_error() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Gone Atlas");
        mockMvc.perform(post("/books/{id}/discard", bookId)).andExpect(status().isOk());

        reserve(bookId, memberId)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void reserving_the_same_book_twice_returns_409_with_already_reserved_error() throws Exception {
        String lender = registerMember();
        String memberId = registerMember();
        String bookId = registerBook("Twice Reserved Atlas");
        loanBook(bookId, lender);
        reserve(bookId, memberId).andExpect(status().isCreated());

